style.css:
/* Smooth Cyberpunk Retro Theme for Arc */

/* Body background and base text */
body {
    background-color: #0b0b1a !important;
    color: #a0fff8 !important;
    font-family: 'Fira Code', 'Courier New', monospace !important;
    transition: background 0.3s ease, color 0.3s ease;
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
    color: #ff77ff !important;
    text-shadow: 0 0 6px rgba(255, 119, 255, 0.5);
}

/* Links */
a {
    color: #ff77ff !important;
    text-decoration: none;
    transition: color 0.3s ease, text-shadow 0.3s ease;
}
a:hover {
    color: #00f0ff !important;
    text-shadow: 0 0 8px #00f0ff, 0 0 16px #ff77ff;
}

/* Buttons */
button {
    background: linear-gradient(145deg, #111122, #1a1a33) !important;
    color: #a0fff8 !important;
    border: 1px solid #00fff0 !important;
    border-radius: 12px !important;
    padding: 6px 14px !important;
    box-shadow: 0 4px 15px rgba(0, 255, 240, 0.3);
    transition: all 0.3s ease;
    font-family: 'Fira Code', monospace !important;
}
button:hover {
    background: linear-gradient(145deg, #1a1a33, #222244) !important;
    color: #ff77ff !important;
    box-shadow: 0 6px 20px rgba(255, 119, 255, 0.5);
    transform: scale(1.03);
}

/* Input buttons */
input[type="button"], input[type="submit"] {
    background: linear-gradient(145deg, #111122, #1a1a33) !important;
    color: #a0fff8 !important;
    border: 1px solid #00fff0 !important;
    border-radius: 12px !important;
    padding: 6px 14px !important;
    box-shadow: 0 4px 15px rgba(0, 255, 240, 0.3);
    transition: all 0.3s ease;
    font-family: 'Fira Code', monospace !important;
}
input[type="button"]:hover,
input[type="submit"]:hover {
    background: linear-gradient(145deg, #1a1a33, #222244) !important;
    color: #ff77ff !important;
    box-shadow: 0 6px 20px rgba(255, 119, 255, 0.5);
    transform: scale(1.03);
}

/* Text inputs and textareas */
input[type="text"], input[type="email"], input[type="password"], textarea {
    background-color: #111122 !important;
    color: #a0fff8 !important;
    border: 1px solid #00fff0 !important;
    border-radius: 8px !important;
    padding: 4px 8px !important;
    box-shadow: 0 4px 12px rgba(0, 255, 255, 0.2);
    transition: all 0.3s ease;
}
input:focus, textarea:focus {
    border-color: #ff77ff !important;
    box-shadow: 0 0 12px rgba(255, 119, 255, 0.4);
}

/* Images & videos */
img, video {
    filter: drop-shadow(0 0 8px rgba(0, 255, 255, 0.3));
    transition: transform 0.3s ease;
}
img:hover, video:hover {
    transform: scale(1.02);
}

/* Paragraphs & general text */
p {
    line-height: 1.6;
    color: #a0fff8 !important;
}

/* Code blocks */
code, pre {
    background-color: #111122 !important;
    color: #00f0ff !important;
    border-radius: 8px;
    padding: 4px 8px;
    font-family: 'Fira Code', monospace !important;
    box-shadow: 0 2px 10px rgba(0, 255, 255, 0.1);
}
